import {stories,storyList,discussStory} from './stories.js?v=1';
let preferredVoice='';try{preferredVoice=localStorage.getItem('campus-voice')||'';}catch{}
let voiceConfirmed=false,voiceTested=false,textOnly=false;try{voiceConfirmed=localStorage.getItem('campus-voice-confirmed')==='1';}catch{}
const speechRates=[.65,.75,.85,1,1.15];let speechRate=.85;try{const saved=Number(localStorage.getItem('campus-speech-rate'));if(speechRates.includes(saved))speechRate=saved;}catch{}
let speechRequest=0,voiceStatus="尚未播放",voiceSaveError=false;
const KEY='campus-quest-v1';let storage=true,s;try{s=restore(localStorage.getItem(KEY));}catch{s=initial();storage=false;}
let view='welcome',subtitles=false,hint=0,message='Hey, explorer! I’m Nova. Ready to find Pip together?',translation='我是 Nova，你的同行教练。你来决定路线，我陪你一起寻找 Pip。',notice='',cluePop='',clueTimer,recording=null,chosen=false,transfer=false;
let player={x:150,y:460},companion={x:115,y:480},destination=null,nearby=null,keys=new Set(),lastFrame=0,lastSave=0,micApproved=false;let mapIntroSeen=false;
let npcLine='',npcZh='',lastQuestion='',heardBy='',micError='';let lastSpoken='';
let npcReplies={},npcResponses={},npcTopics={};let listeningContext=null,discussionActive=false,discussionChecking=false;
let activeStory=null,storyStep=0,storyChecking=false,storyResult=null,storyTries=0;
function rememberSpeaker(n){if(n&&(n.id==='organiser'||n.clue&&s.clues.includes(n.clue))){if(listeningContext!==n.id){discussionActive=false;discussionChecking=false;}listeningContext=n.id;}}
function discuss(id,text='换个说法'){const n=NPCS.find(n=>n.id===id);if(!n)return;rememberSpeaker(n);discussionActive=true;const answer=discussClue(s,n.id,text);discussionChecking=answer.checking;coachStatus='正在讨论 '+n.name.split(' · ')[0]+' 的线索 · 可继续开口追问';say(answer.en,answer.zh);speak(answer.en,true);document.querySelector('#coach-panel')?.scrollIntoView({block:'center',behavior:'smooth'});}
function npcAudio(n){if(s.complete)return reply(n,s,'');if(n.id==='organiser'&&s.started)return missionBrief;if(npcReplies[n.id])return npcReplies[n.id];if(n.clue&&s.clues.includes(n.clue)){const r=reply(n,s,'Have you seen Pip?');return {en:r.en,zh:r.zh};}return null;}
function replayNpc(n){const audio=npcAudio(n);if(!audio)return;rememberSpeaker(n);heardBy=n.id;npcLine=audio.en;npcZh=audio.zh;lastQuestion='';render();speak(audio.en);}
try{const p=JSON.parse(localStorage.getItem('campus-position'));if(Number.isFinite(p?.x)&&Number.isFinite(p?.y))player=bound(p);}catch{}
nearby=nearest(player,s);
message=guidance(s).en;translation=guidance(s).zh;let guideHighlight='',coachStatus='';
const places={plaza:{name:'科技节广场',en:'Festival Plaza',icon:'🎪',x:17,y:52},library:{name:'图书馆',en:'Library',icon:'🏛️',x:51,y:46},art:{name:'美术教室',en:'Art Room',icon:'🎨',x:82,y:49},greenhouse:{name:'温室',en:'Greenhouse',icon:'🌿',x:51,y:17},gym:{name:'体育馆',en:'Gym',icon:'🏀',x:51,y:80}};
const clues={witness:['目击记录','Pip went past the library, towards the art room.','Pip 经过图书馆，向美术教室走去。'],record:['设备记录','10:20 — blue light flashing.','10:20，蓝灯闪烁。Pip 追逐明亮物品时会闪蓝灯。'],decoration:['装饰物的去向','We carried a shiny decoration to the greenhouse.','美术社把闪亮的装饰物搬到了温室。']};
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,act,cls='secondary',extra='')=>`<button class="${cls}" data-action="${act}" ${extra}>${text}</button>`;
function transcript(en,zh){return `<details class="transcript" ${textOnly?'open':''}><summary>需要文字帮助</summary><p lang="en">${esc(en)}</p><details ${textOnly?'open':''}><summary>查看中文意思</summary><p>${esc(zh)}</p></details></details>`;}
function audioPrompt(){return '<div class="audio-prompt" aria-label="听力优先">🎧 <span>先听一听，再开口</span><small>没听清？重听一次，或放慢语速。</small></div>';}
function openTyping(target){const form=document.querySelector(target==='coach'?'#talk':target==='story'?'#story-talk':'#npc-talk');if(form){form.closest('details').open=true;form.querySelector('input')?.focus();}}
function commit(a,v){const prev=guidance(s).en;s=transition(s,a,v);if(guidance(s).en!==prev){message=guidance(s).en;translation=guidance(s).zh;}try{localStorage.setItem(KEY,JSON.stringify(s));}catch{storage=false;}}
function say(en,zh){message=en;translation=zh;render();}
function stopSpeech(){speechRequest++;window.speechSynthesis?.cancel();}
async function speak(text,slow=false,onEnd){
 lastSpoken=text;
 if(recording)cancelVoice(true);
 if(textOnly)return;
 if(!('speechSynthesis' in window)){notice='此浏览器不支持语音播放，可以阅读文字继续。';render();return;}
 const request=++speechRequest,synth=window.speechSynthesis;
 synth.cancel();
 voiceStatus='正在等待所选音色加载…';updateVoiceStatus();
 const voices=await loadVoices(synth,2500,vs=>!!chooseVoice(vs,preferredVoice));
 if(request!==speechRequest)return;
 const voice=chooseVoice(voices,preferredVoice);
 if(!voice){voiceStatus='所选音色不可用：已停止播放，没有切换到其他声音。';notice=preferredVoice?'保存的音色未被此浏览器提供，请在语言背包中选择一个可用音色。':'此浏览器没有提供 Google US English。已停止播放，避免偷偷换成其他声音。请在语言背包选择可用音色，或用提供 Google US English 的浏览器打开。';render();return;}
 const u=new SpeechSynthesisUtterance(text);
 u.voice=voice;u.lang=voice.lang;u.rate=slow?Math.max(.5,speechRate*.8):speechRate;u.pitch=1;u.volume=1;
 voiceStatus='本次指定音色：'+voice.name+' · '+voice.lang+' · '+u.rate.toFixed(2)+'×';updateVoiceStatus();
 u.onerror=e=>{if(request!==speechRequest||['canceled','interrupted'].includes(e.error))return;notice='当前英语音色播放失败，请换一个音色或浏览器重试。';render();};
 u.onend=()=>{if(request===speechRequest){voiceTested=true;const b=document.querySelector('[data-action=voice-confirm]');if(b)b.disabled=false;}if(typeof onEnd==='function')onEnd();};
 synth.resume();synth.speak(u);
}
function voiceOptions(){const voices=englishVoices(window.speechSynthesis?.getVoices()||[]),selected=chooseVoice(voices,preferredVoice);let html=`<option value="" ${!preferredVoice?'selected':''}>Google US English · 默认${chooseVoice(voices)?'':'（当前不可用）'}</option>`;if(preferredVoice&&!selected)html+=`<option value="${esc(preferredVoice)}" selected>已保存的音色（当前不可用）</option>`;return html+voices.map(v=>`<option value="${esc(voiceKey(v))}" ${preferredVoice&&selected===v?'selected':''}>${esc(v.name)} · ${esc(v.lang)}</option>`).join('');}
function selectedVoiceLabel(){const v=chooseVoice(window.speechSynthesis?.getVoices()||[],preferredVoice);return v?v.name+' · '+v.lang:(preferredVoice?'已保存的音色不可用':'Google US English 当前不可用');}
function updateVoiceStatus(){document.querySelectorAll('[data-voice-status]').forEach(el=>el.textContent=voiceStatus);document.querySelectorAll('[data-selected-voice]').forEach(el=>el.textContent='所选音色：'+selectedVoiceLabel());}
function rateSettings(id){return `<div class="rate-settings"><label for="${id}">英语语速</label><select id="${id}" data-rate-choice aria-label="英语语速">${speechRates.map(r=>`<option value="${r}" ${speechRate===r?'selected':''}>${r.toFixed(2)}× · ${({0.65:'很慢',0.75:'慢速',0.85:'舒缓（默认）',1:'正常',1.15:'稍快'})[r]}</option>`).join('')}</select><small>随时可调，所有英语播放共用。</small></div>`;}
function voiceSettings(){return `<div class="voice-settings"><label for="voice-choice">英语音色</label><select id="voice-choice">${voiceOptions()}</select>${rateSettings('voice-rate')}${btn('试听音色和语速','voice-preview','chip')}<small data-selected-voice>所选音色：${esc(selectedVoiceLabel())}</small><small data-voice-status>${esc(voiceStatus)}</small><small>${voiceSaveError?'浏览器未允许保存，关闭页面后可能需要重新选择。':'选择会保存在此浏览器，刷新和重玩都不需要重设。'} 所选音色缺失时停止播放，不自动替换。</small></div>`;}

function goal(){if(s.complete)return'🎉 任务完成！你找到了 Pip';if(!s.started)return'在广场领取寻找 Pip 的任务';if(s.clues.length<3)return`探索校园，收集线索 ${s.clues.length}/3`;if(!s.discovered)return'根据收集到的线索，探索可能的藏身处';if(!s.complete)return'🤖 你发现了 Pip！点击它，听它的感谢';return'任务完成！试试新的位置挑战';}
function prep(){return `<section class="card prep"><div class="eyebrow">BEFORE THE ADVENTURE</div><h2 style="margin-top:10px">装好你的语言背包</h2><p class="muted">先认识本关会遇到的词。点卡片听发音，冒险时也能回来查看。</p>${voiceSettings()}<div class="vocabgrid">${[['🤖','robot','机器人'],['🏛️','library','图书馆'],['🌿','greenhouse','温室'],['↩','behind','在……后面'],['✨','flashing','闪烁的'],['🟢','button','按钮']].map(([i,w,z])=>`<button class="word" data-speak="${w}"><em>${i}</em><b>${w} <small>◖))</small></b><span>${z}</span></button>`).join('')}</div><div class="phrases">${['Have you seen a small robot?','Could you say that again?','Let’s check the library.'].map(t=>`<button class="phrase" data-speak="${t}">◖)) &nbsp; ${t}</button>`).join('')}</div><div class="actions">${btn(s.prepared?'返回探索 →':'准备好了，出发 →','begin','primary')}</div></section>`;}
function celebrate(){
 if(!s.complete||document.querySelector('#victory'))return;
 const stars=s.practice<=4?3:s.practice<=8?2:1;
 destination=null;keys.clear();cancelVoice();
 const d=document.createElement('dialog');d.id='victory';d.className='victory';d.setAttribute('aria-labelledby','victory-title');
 d.innerHTML=`<div class="confetti" aria-hidden="true">${Array.from({length:48},(_,i)=>`<i style="--x:${(i*37)%100}%;--delay:${(i%8)*.12}s;--turn:${i%2?720:-540}deg;--color:${['#f3c66a','#71c8b0','#f39898','#a4a5ea'][i%4]}"></i>`).join('')}</div><div class="victory-body"><div class="victory-banner">🏆 关卡完成 · LEVEL CLEAR</div><div class="victory-seal" aria-hidden="true"><span>⭐</span><b>🤖</b><span>⭐</span></div><div class="eyebrow">MISSION COMPLETE</div><h2 id="victory-title">你找到了 Pip！</h2><p>任务完成 · 探索员，干得漂亮！</p><div class="victory-stars" aria-label="评分 ${stars} 星">${'★'.repeat(stars)}<span class="dim">${'☆'.repeat(3-stars)}</span></div><div class="victory-badge">🏅 校园寻踪者</div><div class="victory-stats"><span>🎧 3 / 3 线索</span><span>🎙 ${s.practice} 次交流</span></div><div class="actions"><button class="primary" id="victory-explore" autofocus>继续探索</button><button class="secondary" id="victory-review">冒险回顾</button></div><button class="chip" id="victory-listen">🔊 再听祝贺</button></div>`;
 document.body.append(d);d.addEventListener('close',()=>{stopSpeech();d.remove();document.querySelector('#world')?.focus({preventScroll:true});},{once:true});
 d.querySelector('#victory-explore').onclick=()=>{d.close();view='map';render();};
 d.querySelector('#victory-review').onclick=()=>{d.close();view='review';render();};
 d.querySelector('#victory-listen').onclick=()=>speak('Congratulations! You found Pip! Thank you for helping. You are a great explorer!');
 d.showModal();speak('Congratulations! You found Pip! Thank you for helping. You are a great explorer!');
}
function winPip(){
 if(s.complete||document.querySelector('#victory'))return;
 destination=null;keys.clear();cancelVoice();
 commit('complete');
 const pip=NPCS.find(n=>n.id==='pip');
 const r=reply(pip,s,'');
 heardBy='pip';npcLine=r.en;npcZh=r.zh;npcReplies.pip=r;
 render();
 if(textOnly||!('speechSynthesis' in window)){celebrate();return;}
 speak(r.en,false,()=>{if(s.complete&&!document.querySelector('#victory'))celebrate();});
}
function encounter(){
 const n=nearest(player,s);
 if(s.complete){const r=reply(n||NPCS[0],s,'');return `<h2>🎉 任务完成！</h2>${audioPrompt()}<div class="actions">${btn('🔊 听感谢','completion-replay','primary')}${btn('慢速重听','completion-slow')}${btn('冒险回顾','review','chip')}${btn('🎉 重播庆祝','celebrate','chip')}</div>${transcript(r.en,r.zh)}`;}
 if(!s.prepared)return `<h2>先准备语言背包</h2>${btn('开始准备','prep','primary')}`;
 if(!n)return `<div class="encounter-idle"><b>走近人物，开始交流</b><p>点击地面 / WASD 移动 · ? 交谈 · 🔊 重听</p></div>`;
 const title=`<div class="encounter-title"><span class="npc-portrait">${n.icon}</span><div><small>${n.id==='organiser'?'任务发布者':'面对面交流'}</small><h2>${n.name}</h2></div></div>`;
 if(n.id==='organiser')return `${title}${audioPrompt()}<div class="actions">${btn(s.started?'🔊 重听任务':'🔊 听取并领取任务',s.started?'mission-replay':'start','primary')}${s.started?btn('慢速重听','mission-slow')+btn('和教练讨论','discuss','chip','data-value="organiser"'):''}</div>${s.started?transcript(missionBrief.en,missionBrief.zh):'<small>点击问号或按 E，听她介绍。</small>'}`;
 const audio=npcResponses[n.id]||npcAudio(n);
 return `${title}${voicePanel('npc',n.id)}${audioPrompt()}<div class="actions">${voiceTriggerButton('npc','开口提问')}${btn('🔊 重听回答','npc-replay','secondary',audio?'':'disabled')}${btn('慢速重听','npc-slow','secondary',audio?'':'disabled')}${audio&&n.clue&&s.clues.includes(n.clue)?btn('和教练讨论','discuss','chip',`data-value="${n.id}"`):''}</div>${audio?transcript(audio.en,audio.zh):''}<details class="typing-fallback" ${textOnly?'open':''}><summary>暂时无法开口？打字交流</summary><form id="npc-talk" class="npc-form"><label for="npc-question">输入英语问题</label><div><input id="npc-question" name="question" maxlength="300" placeholder="输入你想说的话" autocomplete="off"><button class="secondary" type="submit">发送 ↗</button></div></form></details>${lastQuestion&&heardBy===n.id?`<details><summary>查看语音识别结果</summary><p>${esc(lastQuestion)}</p></details>`:''}<p class="muted" role="status">${esc(micError||'按 E 开口交流')}</p>`;
}
function map(){return `<section class="card adventure"><div class="maphead"><strong>校园自由探索</strong><span class="muted">WASD / ↑↓←→ · 点击地面移动</span></div><div class="map-goal">${goal()}</div>${!mapIntroSeen?`<div class="map-hint" role="status">👟 走近人物才能交谈：用方向键 / WASD 或点击地面移动，靠近后点红色 <b>?</b> 即可对话。<button class="chip" data-action="map-hint-dismiss">知道了</button></div>`:''}<div id="world" class="world" tabindex="0" role="group" aria-label="校园探索区域，使用方向键或 WASD 移动，E 键提问"><div class="world-path horizontal"></div><div class="world-path vertical"></div>${Object.entries(places).map(([id,p])=>`<div class="world-building" style="left:${p.x}%;top:${p.y-9}%"><span>${p.icon}</span><b>${p.name}</b></div>`).join('')}${[[8,15],[26,14],[72,13],[90,17],[9,77],[27,88],[87,81],[65,86]].map(([x,y])=>`<span class="world-tree" style="left:${x}%;top:${y}%">🌳</span>`).join('')}${visibleNPCs(s).map(n=>`<button class="world-npc" data-npc="${n.id}" style="left:${n.x/10}%;top:${n.y/6}%" aria-label="走向${n.name}"><span class="quest-marker" title="点击这里，直接提问" hidden>?</span><span class="sprite">${n.icon}</span><span class="npc-name">${n.name.split(' · ')[0]}</span></button>`).join('')}<div id="destination" class="destination" hidden>◎</div><div id="player" class="world-actor player" style="left:${player.x/10}%;top:${player.y/6}%"><span>🧑‍🚀</span><small>你</small></div><div id="companion" class="world-actor follower" ${s.mode==='voice'?'hidden':''}><span>👩🏻‍🚀</span><small>Nova</small></div><div id="following-pip" class="world-actor" ${!s.following?'hidden':''}><span>🤖</span></div></div><div class="walk-controls"><span>${s.complete?"任务完成 · 点 🔊 重听感谢":s.discovered?"点击 Pip 🤖，听它的感谢":s.started?"点红色 <b>?</b> 提问 · 点 <b>🔊</b> 重听回答":"点 Mia 的 <b>?</b>，听取并领取任务"}</span><div>${btn('↑','walk','chip','data-value="up" aria-label="向上走"')}${btn('←','walk','chip','data-value="left" aria-label="向左走"')}${btn('↓','walk','chip','data-value="down" aria-label="向下走"')}${btn('→','walk','chip','data-value="right" aria-label="向右走"')}</div></div><section id="encounter" class="encounter">${encounter()}</section></section><div class="bottomcards"><section class="card compact"><b>🎯 任务追踪</b>${questTracker(false)}<p class="quest-goal">${goal()}</p><span class="muted">你来行动，Nova 只提供指导。</span></section><section class="card compact"><b>▤ 线索 ${s.clues.length} / 3</b><p>亲自询问人物，回答会自动播放。</p>${btn('打开线索本 ↗','notebook','chip')}</section></div>`;}
function refreshEncounter(){const el=document.querySelector('#encounter');if(el)el.innerHTML=encounter();}
function targetNpc(id){const n=visibleNPCs(s).find(n=>n.id===id);if(!n)return;destination=bound({x:n.x-42,y:n.y+42});document.querySelector('#world')?.focus({preventScroll:true});}
function npcSubmit(text){if(recording)cancelVoice();const n=nearest(player,s);if(!n||!s.prepared||!text.trim())return;stopSpeech();commit('move',n.location);commit('practice');heardBy=n.id;lastQuestion=text;micError='';const r=reply(n,s,text,{topicEstablished:npcTopics[n.id]===true});if(mentionsTask(text))npcTopics[n.id]=true;if(r.repeat){const prior=npcResponses[n.id]||npcAudio(n);npcLine=prior?.en||'I haven’t shared a clue yet. What would you like to ask?';npcZh=prior?.zh||'我还没提供线索，你想问什么？';npcResponses[n.id]={en:npcLine,zh:npcZh};render();speak(npcLine,true);return;}if(r.clue){commit('clue',r.clue);cluePop='🎉 新线索 +1 · '+n.name.split(' · ')[0]+' 提供了 Pip 的踪迹';clearTimeout(clueTimer);clueTimer=setTimeout(()=>{cluePop='';render();},2600);}if(r.follow)commit('follow');if(r.reveal)chosen=true;npcLine=r.en;npcZh=r.zh;npcResponses[n.id]={en:r.en,zh:r.zh};if(r.clue||!n.clue)npcReplies[n.id]={en:r.en,zh:r.zh};if(r.clue)rememberSpeaker(n);render();speak(r.en);}
function frame(time){const dt=Math.min((time-lastFrame)/1000||0,.05);lastFrame=time;
 if(view==='map'&&!document.querySelector('dialog')&&!recording){let dx=(keys.has('arrowright')||keys.has('d')?1:0)-(keys.has('arrowleft')||keys.has('a')?1:0),dy=(keys.has('arrowdown')||keys.has('s')?1:0)-(keys.has('arrowup')||keys.has('w')?1:0);const before={...player};if(dx||dy){destination=null;const len=Math.hypot(dx,dy);player=bound({x:player.x+dx/len*175*dt,y:player.y+dy/len*175*dt});}else if(destination){player=step(player,destination,175*dt);if(distance(player,destination)<1)destination=null;}
 if(distance(companion,player)>45)companion=step(companion,player,185*dt);
 if(view==='map'&&canDiscover(s,player)){commit('move','greenhouse');commit('discover');notice='🤖 你根据线索找到了 Pip！走近一点，点一下 Pip，听听它的感谢。';guideHighlight='';destination=null;keys.clear();render();}
 const n=nearest(player,s);if(n?.id!==nearby?.id){nearby=n;chosen=false;npcLine='';npcZh='';lastQuestion='';heardBy='';micError='';refreshEncounter();}if(n&&s.location!==n.location)commit('move',n.location);
 if(distance(before,player)>.01&&time-lastSave>500){lastSave=time;try{localStorage.setItem('campus-position',JSON.stringify(player));}catch{}}
 }
 const set=(id,p)=>{const el=document.getElementById(id);if(el){el.style.left=p.x/10+'%';el.style.top=p.y/6+'%';}};set('player',player);set('companion',companion);set('following-pip',bound({x:companion.x-28,y:companion.y+30}));const dest=document.querySelector('#destination');if(dest){dest.hidden=!destination;if(destination)set('destination',destination);}
 document.querySelectorAll('.world-npc').forEach(el=>{const n=NPCS.find(n=>n.id===el.dataset.npc);const near=nearest(player,s)?.id===n.id;el.classList.toggle('near',near);el.classList.toggle('guide-target',n.id===guideHighlight);if(near&&n.id===guideHighlight)guideHighlight='';const issuing=interactionMode(n,s)==='mission',audio=npcAudio(n),marker=el.querySelector('.quest-marker'),pipWin=n.id==='pip'&&s.discovered&&!s.complete;marker.hidden=!(near&&(audio||hasInformation(n,s)||pipWin));marker.textContent=pipWin?'🤖':audio?'🔊':'?';marker.classList.toggle('replay-marker',!!audio);marker.title=pipWin?'点击 Pip，听它的感谢':audio?'点击重听这个人物的回答':issuing?'点击听取并领取任务':'点击这里，直接提问';el.setAttribute('aria-label',near&&s.prepared?(pipWin?'点击 Pip，听它的感谢':audio?'重听'+n.name+'的回答':issuing?'听取并领取 Mia 的任务':'向'+n.name+'提问'):'走向'+n.name);el.title=near?(pipWin?'点击 Pip 🤖，听它的感谢':audio?'点击喇叭重听人物的话':issuing?'点击问号，领取任务':'点击人物或问号，直接提问'):'走到人物身边';});requestAnimationFrame(frame);
}
function notebook(){return `<section class="card notebook"><div class="eyebrow">AUDIO CLUES</div><h2>我的语音线索</h2><p class="muted">重新听听他们说了什么，再决定去哪里。</p>${s.clues.length?s.clues.map(c=>{const n=NPCS.find(n=>n.clue===c),r=reply(n,s.complete?{...s,complete:false}:s,'Have you seen Pip?');return `<div class="clue"><b>${n.icon} ${n.name.split(' · ')[0]}</b><div class="actions">${btn('🔊 重听线索','clue-listen','primary',`data-value="${c}"`)}${btn('慢速重听','clue-slow','secondary',`data-value="${c}"`)}${btn('和教练讨论','discuss','chip',`data-value="${n.id}"`)}</div>${transcript(r.en,r.zh)}</div>`;}).join(''):'<div class="hero-icon">🎧</div><p>还没有收集到语音线索。</p>'}${btn('返回地图','map','primary')}</section>`;}

function review(){if(!s.complete)return `<section class="card review"><h2>冒险还在继续</h2><p>${goal()}</p>${btn('继续探索','map','primary')}</section>`;return `<section class="card review"><div class="eyebrow">MISSION ACCOMPLISHED</div><div class="hero-icon">🤖 🌟</div><h2>恭喜！你找到了 Pip！</h2><p>你询问了目击者，连接起线索，亲手完成了任务。</p><div class="stats"><div><b>3 / 3</b><small>收集线索</small></div><div><b>${s.practice}</b><small>英语提交次数（含文字）</small></div></div><div class="clue">🎙 可选：用英语和 Nova 分享你的发现。</div><div class="exercise"><b>换个场景，还能听懂吗？</b><p>播放新的位置描述，再选择目的地。</p>${btn('◖)) 听新线索','transfer-audio')} ${btn('慢速重听','transfer-slow','chip')}<div class="actions" style="margin-top:14px">${btn('体育馆后面','transfer-right')}${btn('图书馆前面','transfer-wrong')}</div><p role="status">${transfer?'✓ 正确，你理解了新地点的位置关系。':''}</p></div><p class="muted">原型不评估发音或语言等级。这里展示的是实际任务与练习记录。</p>${btn('🎉 重播庆祝','celebrate','primary')}${btn('再玩一次','reset','secondary')}</section>`;}
function voiceSetup(){return `<section class="card prep"><div class="eyebrow">FIRST · CHOOSE YOUR VOICE</div><h2>先选适合你的音色和语速</h2><p>选择音色和语速，再点击试听。默认 0.85×，你可以调慢或调快，听清楚后再开始冒险。</p>${voiceSettings()}<div class="actions">${btn('听清楚了，使用这些设置 →','voice-confirm','primary',voiceTested?'':'disabled')}${btn('暂时使用文字进入','voice-skip')}</div><p class="muted">确认后会记住选择。冒险中可在教练面板随时调速，语言背包可更换音色；暂用文字不会跳过下次的音色设置。</p></section>`;}
function welcome(){return activeStory?storyDetail():storiesHub(false);}

function storySelect(id){activeStory=id;storyStep=0;storyChecking=false;storyResult=null;storyTries=0;micError='';render();if(!textOnly&&stories[id])speak(stories[id].simple[0]);}
function storyBack(){activeStory=null;storyStep=0;storyChecking=false;storyResult=null;storyTries=0;micError='';render();}
function storyAnswer(text){if(!activeStory||!text.trim())return;const d=stories[activeStory];storyTries++;stopSpeech();micError='';const r=discussStory(activeStory,text,true);storyChecking=r.checking;const right=!r.checking&&r.en===d.feedback[0];storyResult={en:r.en,zh:r.zh,checking:r.checking,right};render();speak(r.en);if(right)setTimeout(storyCelebrate,400);}
function storiesHub(){
 return `<section class="card stories"><p class="muted">选一个故事开始：装好语言背包、进入冒险地图开口回答、翻看线索手记、最后冒险回顾。每个故事都是一次完整的听说冒险。</p><div class="story-list">${storyList.map(s=>{const d=stories[s.id];const hook=d.simple[1];return `<button class="story-card" data-action="story-select" data-value="${s.id}"><span class="story-topic">${esc(s.topic)}</span><span class="story-name">${esc(d.name)}</span><span class="story-hook">${esc(hook.length>22?hook.slice(0,22)+'…':hook)}</span><span class="story-go">开始 ▶</span></button>`;}).join('')}</div></section>`;
}
function storyDetail(){
 const d=stories[activeStory];
 const top=`<div class="story-top">${btn('← 故事列表','story-back','chip')}<span class="story-topic">${esc(d.topic)}</span></div>`;
 let body='';
 if(storyStep===0){
  body=`<div class="story-prep"><b>▧ 语言背包</b><p class="muted">先认识本故事会遇到的词。点卡片听发音，冒险时也能回来查看。</p><div class="vocabgrid">${Object.entries(d.terms).map(([w,t])=>`<button class="word" data-speak="${esc(w)}"><em>🔊</em><b>${esc(w)}</b><span>${esc(t[1])}</span></button>`).join('')}</div><div class="actions">${btn('下一个：冒险地图 →','story-step','primary','data-value="1"')}</div></div>`;
 } else if(storyStep===1){
  body=`<div class="story-map"><b>◈ 冒险地图</b><p class="muted">听故事，再用英语回答下面的问题。</p><div class="story-narrative"><p lang="en">${esc(d.simple[0])}</p><p>${esc(d.simple[1])}</p><div class="actions">${btn('🔊 播放故事','story-listen','primary')}${btn('慢速重听','story-slow','secondary')}</div></div><div class="story-check"><b>📝 ${esc(d.check[1])}</b><p lang="en">${esc(d.check[0])}</p></div><div class="story-answer">${voicePanel('story')}<div class="actions">${voiceTriggerButton('story','🎙 开口回答')}</div>${micError?`<p class="muted" role="status">${esc(micError)}</p>`:''}<details class="typing-fallback" ${textOnly?'open':''}><summary>暂时无法开口？打字回答</summary><form id="story-talk"><label for="story-answer">用英语回答</label><div><input id="story-answer" name="answer" maxlength="300" placeholder="输入你的回答" autocomplete="off"><button class="secondary" type="submit">提交 ↗</button></div></form></details>${storyResult?`<div class="story-feedback ${storyResult.right?'right':(storyResult.checking?'retry':'info')}"><b>${storyResult.right?'✅ 答对啦！':'💡 再试试看'}</b><p lang="en">${esc(storyResult.en)}</p><p>${esc(storyResult.zh)}</p><div class="actions">${btn('🔊 再听','story-listen','chip')}</div></div>`:'<small class="muted">听完故事，用英语回答上面的问题。</small>'}</div><div class="actions">${btn('← 语言背包','story-step','chip','data-value="0"')}</div></div>`;
 } else if(storyStep===2){
  body=`<div class="story-notebook"><b>▤ 线索手记</b><p class="muted">回顾一下今天学到的内容。</p><div class="story-narrative"><p lang="en">${esc(d.simple[0])}</p><p>${esc(d.simple[1])}</p><div class="actions">${btn('🔊 重听故事','story-listen','primary')}${btn('慢速重听','story-slow','secondary')}</div></div><div class="vocabgrid">${Object.entries(d.terms).map(([w,t])=>`<button class="word" data-speak="${esc(w)}"><em>🔊</em><b>${esc(w)}</b><span>${esc(t[1])}</span></button>`).join('')}</div><div class="actions">${btn('← 冒险地图','story-step','chip','data-value="1"')}${btn('下一个：冒险回顾 →','story-step','primary','data-value="3"')}</div></div>`;
 } else {
  const stars=storyTries<=4?3:storyTries<=8?2:1;
  body=`<div class="story-review"><div class="eyebrow">STORY COMPLETE</div><div class="hero-icon">📖 🌟</div><h2>太棒了，你完成了《${esc(d.name)}》！</h2><p>你听懂了故事，说出了自己的理解。</p><div class="victory-stars" aria-label="评分 ${stars} 星">${'★'.repeat(stars)}<span class="dim">${'☆'.repeat(3-stars)}</span></div><div class="actions">${btn('🔊 重听故事','story-listen','primary')}${btn('🎉 重播庆祝','story-celebrate','secondary')}${btn('返回故事列表','story-back','chip')}</div></div>`;
 }
 return `<section class="card stories detail">${top}<h2>📖 ${esc(d.name)} 的故事</h2>${body}</section>`;
}
function storiesView(){return activeStory?storyDetail():storiesHub(true);}
function storiesAside(){return `<aside class="card coach-intro stories-aside"><div class="avatar">🎧</div><strong>听说小练习</strong><p>7 个日常场景，随时来练。</p><div class="story-tips"><small>🎧 先听故事，可常速或慢速重听</small><small>🗂 点词卡直接听发音</small><small>🎙 开口回答，也可以打字提交</small><small>💡 答错会给出提示，可以再试</small></div></aside>`;}
function storyNav(){
 const home=btn('🏠 返回主页','story-back','home');
 const steps=[['prep','▧ 语言背包'],['map','◈ 冒险地图'],['notebook','▤ 线索手记'],['review','☆ 冒险回顾']];
 return `<nav class="nav story-nav" aria-label="本故事导航">${home}<span class="nav-sep" role="separator" aria-hidden="true"></span>${steps.map(([,label],i)=>btn((i<storyStep?'✓ ':'')+label,'story-step',i===storyStep?'active':'',`data-value="${i}"`)).join('')}</nav>`;
}
function storyCelebrate(){
 if(document.querySelector('#victory'))return;
 const d=stories[activeStory];const stars=storyTries<=4?3:storyTries<=8?2:1;
 cancelVoice();
 const el=document.createElement('dialog');el.id='victory';el.className='victory';el.setAttribute('aria-labelledby','victory-title');
 el.innerHTML=`<div class="confetti" aria-hidden="true">${Array.from({length:48},(_,i)=>`<i style="--x:${(i*37)%100}%;--delay:${(i%8)*.12}s;--turn:${i%2?720:-540}deg;--color:${['#f3c66a','#71c8b0','#f39898','#a4a5ea'][i%4]}"></i>`).join('')}</div><div class="victory-body"><div class="victory-banner">🏆 故事完成 · LEVEL CLEAR</div><div class="victory-seal" aria-hidden="true"><span>⭐</span><b>📖</b><span>⭐</span></div><div class="eyebrow">STORY COMPLETE</div><h2 id="victory-title">你讲出了《${esc(d.name)}》！</h2><p>任务完成 · 探索员，干得漂亮！</p><div class="victory-stars" aria-label="评分 ${stars} 星">${'★'.repeat(stars)}<span class="dim">${'☆'.repeat(3-stars)}</span></div><div class="victory-stats"><span>🎧 听故事</span><span>🎙 ${storyTries} 次开口</span></div><div class="actions"><button class="primary" id="victory-explore" autofocus>继续探索</button><button class="secondary" id="victory-review">冒险回顾</button></div><button class="chip" id="victory-listen">🔊 再听祝贺</button></div>`;
 document.body.append(el);el.addEventListener('close',()=>{stopSpeech();el.remove();},{once:true});
 el.querySelector('#victory-explore').onclick=()=>{el.close();storyStep=2;render();};
 el.querySelector('#victory-review').onclick=()=>{el.close();storyStep=3;render();};
 el.querySelector('#victory-listen').onclick=()=>speak('Great job! You finished the story!');
 el.showModal();speak('Great job! You finished the story!');
}
function planBanner(){return `<div class="plan-banner"><span>👩🏻‍🚀</span><div><small>NOVA · 随时陪你</small><p>不知道下一步？听听教练的建议。</p></div>${btn('🔊 听下一步','coach-next','primary')}</div>`;}

function coach(){const g=guidance(s);return `<aside class="card coachpanel" id="coach-panel"><div class="coachhead"><div class="avatar">👩🏻‍🚀</div><div><strong>Nova / 同行教练</strong><div class="online">● 听说优先</div></div></div>${rateSettings('coach-rate')}${voicePanel('coach')}${listeningContext?`<div class="discussion-tools"><small>讨论 ${esc(NPCS.find(n=>n.id===listeningContext).name.split(' · ')[0])} 的线索</small><div class="actions">${btn('换个说法','discuss-simple','chip')}${btn('解释关键词','discuss-words','chip')}${btn('检查我的理解','discuss-check','chip')}</div><small>本关预设线索讨论</small></div>`:''}<div class="conversation">${audioPrompt()}<div class="tools">${btn('🔊 重听','listen','primary')}${btn('慢速重听','slow')}${btn('停止','stop')}</div>${transcript(message,translation)}<div class="coach-quick">${voiceTriggerButton('coach','和教练说话')}${btn('听下一步','coach-next')}${btn('听表达示范','phrase-help')}</div></div><div class="composer"><p class="status" id="voice-status" role="status">${esc(coachStatus||'')}</p><details id="coach-typing" ${textOnly?'open':''}><summary>暂时无法开口？打字交流</summary><form id="talk"><label for="utterance">问问教练</label><input id="utterance" name="utterance" autocomplete="off" maxlength="300" placeholder="输入你想说的话" aria-label="向教练提问"><button type="submit" class="secondary">发送 ↗</button></form></details><details><summary>更多帮助与设置</summary>${btn(g.cta,'guide-target','chip')}<div class="voice-summary"><small data-selected-voice>所选音色：${esc(selectedVoiceLabel())}</small><small data-voice-status>${esc(voiceStatus)}</small></div><div class="modes">${btn('同行陪伴','mode',s.mode==='companion'?'active':'','data-value="companion"')}${btn('语音陪伴','mode',s.mode==='voice'?'active':'','data-value="voice"')}</div>${btn('更换音色','prep','chip')}</details></div></aside>`;}

const isHub=()=>activeStory===null&&(view==='stories'||view==='welcome');
const inStory=()=>activeStory!==null;
function navEnabled(target){return view!=='voice'&&canNavigate(s,target);}
function navHint(target){return !s.entered&&!s.prepared?'点击开始后解锁':target!=='prep'&&!s.prepared?'完成语言准备后解锁':'';}
function questTracker(mini=false){
 const steps=[['领取任务','📋'],['收集线索','🔎'],['找到 Pip','🤖'],['通关','🏁']];
 const cur=!s.started?0:s.discovered?(!s.complete?2:3):1;
 return `<div class="quest${mini?' quest-mini':''}" role="list" aria-label="任务进度">${steps.map(([label,icon],i)=>`<span class="quest-node ${i<cur?'done':''} ${i===cur?'active':''} ${i>cur?'todo':''}" role="listitem"><span class="quest-dot">${i<cur?'✓':icon}</span><span class="quest-label">${label}</span></span>${i<steps.length-1?'<span class="quest-line"></span>':''}`).join('')}</div>`;
}
function render(){const hub=isHub(),story=inStory();document.querySelector('#app').innerHTML=`<div class="shell ${hub?'no-sidebar':''}">${hub?'':`<aside class="sidebar"><div class="brand">campus<span>quest.</span><small>英语同行冒险</small></div>${story?storyNav():`<nav class="nav" aria-label="主导航">${[['prep','▧ 语言背包'],['map','◈ 冒险地图'],['notebook','▤ 线索手记'],['stories','📖 日常故事'],['review','☆ 冒险回顾']].map(([v,t])=>btn(t,v,view===v?'active':'')).join('')}</nav>`}<div class="side-note">${story?'本故事 · 听说练习<br><b>听 → 学 → 说 → 回顾</b><br>按自己的节奏，随时切换。':'YOUR ADVENTURE<br><b>每一次开口，<br>都是新的发现。</b><br>你来探索，教练与你同行。'}</div></aside>`}<main class="workspace ${hub?'title-screen':''}"><div class="topbar hud"><div class="hud-left"><span class="hud-avatar">${hub?'🎧':story?'📖':'🧑‍🚀'}</span><span class="hud-meta"><b>${hub?'听说练习员':story?'故事练习员':'探索员'}</b><small>${hub?'日常故事 · 独立练习':story?'本故事听说练习':'第 01 关 · 校园篇'}</small></span></div>${hub?'<span class="pill">📖 7 个场景 · 随时可玩</span>':story?'<span class="pill">🗂 故事四步</span>':questTracker(true)+'<span class="pill">🌱 A1–A2</span>'}</div>${hub?`<header class="heading"><div><div class="eyebrow">DAILY STORIES</div><h1>日常英语小故事</h1><p>听生活故事，学重点词，开口回答。包含 7 个日常场景，每个都是独立的听说练习。</p></div><span class="pill">◷ 每篇约 5 分钟</span></header>`:story?`<header class="heading"><div><div class="eyebrow">DAILY STORY</div><h1>${esc(stories[activeStory].name)} 的故事</h1><p>${esc(stories[activeStory].topic)} · 听故事、学单词、开口答、回顾。</p></div></header>`:`<header class="heading"><div><div class="eyebrow">THE MISSING ROBOT</div><h1>消失的科技节机器人</h1><p>跟随线索，找到 Pip。校园里的冒险，从你开口开始。</p></div><span class="pill">◷ 约 20 分钟 · 无倒计时</span></header>`}${!storage?'<div class="toast">浏览器存储不可用，本次进度仅保留到页面关闭。</div>':''}${notice?`<div class="toast" role="status">${esc(notice)}</div>`:''}${cluePop?`<div class="clue-pop" role="status">${esc(cluePop)}</div>`:''}<div class="layout ${story?'story-layout':''}"><div>${hub?welcome():story?storyDetail():view==='voice'?voiceSetup():view==='prep'?prep():view==='notebook'?notebook():view==='map'?planBanner()+map():review()}</div>${hub?storiesAside():(story?'':(s.entered||s.prepared?coach():'<aside class="card coach-intro"><div class="avatar">👩🏻‍🚀</div><strong>Nova · 同行教练</strong><p>准备好后，点击开始。</p></aside>'))}</div><footer class="footnote"><span>${hub?'DAILY STORIES · 听说小练习':story?'DAILY STORY · 听说练习':'EPISODE 01 · GREENFIELD CAMPUS'}</span><span>进度保存在此浏览器 · 脚本互动，不含真人联机 &nbsp; ${btn('重置进度','reset','chip')}</span></footer></main></div>`;}
function focusInput(){document.querySelector('#utterance')?.focus();}
function submit(text){if(recording)cancelVoice();if(!text.trim())return;if(/repeat|again|slow|再说|重听/i.test(text)){speak(message,true);return;}const contextual=listeningContext&&!/下一步|next|怎么走|如何移动|keyboard|control|这句话怎么说/.test(text)&&(discussionActive||/听不懂|意思|解释|词|why|mean|understand|detail|said|towards|past|flashing|shiny|followed/i.test(text));const answer=contextual?discussClue(s,listeningContext,text,discussionChecking):coachAnswer(s,text);if(contextual){discussionActive=true;discussionChecking=answer.checking;coachStatus='继续围绕这条线索追问';}else{discussionActive=false;discussionChecking=false;coachStatus='';}say(answer.en,answer.zh);speak(answer.en,contextual);}
function action(a,v){notice='';if(a==='map-hint-dismiss'){mapIntroSeen=true;render();return;}
if(a==='voice-finish'){recording?.stop();return;}
if(a==='voice-cancel'){cancelVoice(true);return;}
if(a==='voice-retry'){if(voiceDisplay)mic(voiceDisplay.target);return;}
if(a==='voice-confirm-text'){if(voiceDisplay?.phase==='review'){voiceDisplay.phase='done';render();deliverVoice(voiceDisplay);}return;}
if(a==='voice-confirm'){if(!voiceTested||!chooseVoice(window.speechSynthesis?.getVoices()||[],preferredVoice))return;voiceConfirmed=true;try{localStorage.setItem('campus-voice-confirmed','1');}catch{voiceSaveError=true;}view='welcome';render();return;}
if(a==='voice-skip'){textOnly=true;stopSpeech();view='welcome';render();return;}
if(view==='voice'&&!['voice-preview','stop','subtitle'].includes(a))return;
if(a==='celebrate'){celebrate();return;}
if(a==='completion-replay'||a==='completion-slow'){speak(reply(nearest(player,s)||NPCS[0],s,'').en,a==='completion-slow');return;}
if(a==='clue-listen'||a==='clue-slow'){const n=NPCS.find(n=>n.clue===v);if(n&&s.clues.includes(v)){rememberSpeaker(n);render();speak(reply(n,{...s,complete:false},'Have you seen Pip?').en,a==='clue-slow');}return;}

if(a==='discuss'){discuss(v);return;}
if(['discuss-simple','discuss-words','discuss-check'].includes(a)){discuss(listeningContext,{'discuss-simple':'换个说法','discuss-words':'解释关键词','discuss-check':'检查理解'}[a]);return;}
if(a==='coach-next'||a==='hint'){submit('下一步做什么');return;}
if(a==='coach-talk'){mic('coach');return;}
if(a==='guide-target'){const g=guidance(s);if(!navEnabled(g.view||'map'))return;if(g.view){view=g.view;render();}else{view='map';guideHighlight=g.target;render();document.querySelector('#world')?.scrollIntoView({block:'center',behavior:'smooth'});}return;}

if(a==='walk'){const d={up:[0,-90],down:[0,90],left:[-90,0],right:[90,0]}[v];destination=bound({x:player.x+d[0],y:player.y+d[1]});return;}
if(a==='mission-replay'||a==='mission-slow'){rememberSpeaker(NPCS.find(n=>n.id==='organiser'));render();speak(missionBrief.en,a==='mission-slow');return;}
if(a==='npc-mic'){mic('npc');return;}
if(a==='npc-replay'||a==='npc-slow'){const n=nearest(player,s),audio=n&&(npcResponses[n.id]||npcAudio(n));if(audio){rememberSpeaker(n);render();speak(audio.en,a==='npc-slow');}return;}
if(['start','finish','green','wrong-button'].includes(a)){const n=nearest(player,s);if(!n||(['start','finish'].includes(a)?n.id!=='organiser':n.id!=='pip'))return;commit('move',n.location);}
if(['map','prep','notebook','review','stories'].includes(a)){if(a==='stories'){keys.clear();destination=null;cancelVoice();stopSpeech();micError='';activeStory=null;storyStep=0;storyChecking=false;storyResult=null;view='welcome';render();return;}if(!navEnabled(a)){commit('enter');view='prep';const g=guidance(s);say(g.en,g.zh);speak(g.en);return;}keys.clear();destination=null;cancelVoice();stopSpeech();micError='';activeStory=null;storyStep=0;storyChecking=false;storyResult=null;view=a;render();return;}if(a==='welcome-home'){cancelVoice();stopSpeech();micError='';activeStory=null;storyStep=0;storyChecking=false;storyResult=null;view='welcome';render();return;}if(a==='story-select'){storySelect(v);return;}if(a==='story-back'){storyBack();return;}if(a==='story-step'){storyStep=Number(v);render();return;}if(a==='story-listen'){if(storyResult&&storyResult.en)speak(storyResult.en);else if(activeStory)speak(stories[activeStory].simple[0]);return;}if(a==='story-slow'){if(activeStory)speak(stories[activeStory].simple[0],true);return;}if(a==='story-mic'){mic('story');return;}if(a==='move'){const n=NPCS.find(n=>n.location===v);if(n)targetNpc(n.id);return;}if(a==='mode'){commit('mode',v);render();return;}if(a==='begin'){if(!navEnabled('prep'))return;commit('prepare');view='map';guideHighlight='organiser';const g=guidance(s);say(g.en,g.zh);speak(g.en);return;}if(a==='start'){if(!s.prepared)return;cancelVoice();destination=null;keys.clear();commit('start');notice='✓ 任务已领取';heardBy='organiser';lastQuestion='';npcLine=missionBrief.en;npcZh=missionBrief.zh;npcReplies.organiser={en:npcLine,zh:npcZh};rememberSpeaker(NPCS.find(n=>n.id==='organiser'));render();speak(npcLine);return;}if(a==='brief'){say('Pip is a small white robot. It has a blue light.','Pip 是白色小机器人，有一盏蓝灯。');return;}if(a==='record'){commit('clue','record');say('The note says: blue light flashing. Pip flashes blue when it follows something bright.','设备记录已收集：蓝灯闪烁。Pip 追逐明亮的物品时会闪蓝灯。');return;}if(a==='ask-library'||a==='ask-art'||a==='ask-follow'){say(a==='ask-library'?'The librarian is listening. What would you like to ask?':a==='ask-art'?'The art club member is here. Ask where the decoration went.':'Pip is ready. Tell it to come with you.',a==='ask-library'?'管理员在听。试着问她是否见过机器人。':a==='ask-art'?'美术社成员就在这里，问问装饰物去了哪里。':'Pip 准备好了，用英语邀请它跟你走。');focusInput();return;}if(a==='example-library'){speak('Have you seen a small robot?');return;}if(a==='gym'){say('I haven’t seen a robot here. Try asking at the library.','工作人员说这里没见过机器人，可以去图书馆问问。');return;}if(a==='blue'){if(s.clues.length<3){say('We need more evidence. Let’s check our notes before choosing.','还需要收集三条线索，才能确认目标。');return;}chosen=true;say('That’s Pip! Press the green button, then wait for the blue light.','找到 Pip 了！按绿色按钮，等待蓝灯亮起。');return;}if(a==='red'||a==='wrong-button'){say('Take another look. What colour did the instructions mention?','再想一想，描述或说明里提到的是哪种颜色？可以重听。');return;}if(a==='green'&&chosen){commit('wake');heardBy='pip';npcLine='I’m awake! Ask me to come with you.';npcZh='我醒了！邀请我跟你一起走吧。';npcReplies.pip={en:npcLine,zh:npcZh};render();speak(npcLine);return;}if(a==='finish'){commit('finish');if(s.complete){view='review';say('You did it! Where did you find Pip?','你完成了任务！试着用英语讲讲在哪里找到了 Pip。');}return;}if(a==='voice-preview'){textOnly=false;speak('Hello! I’m Nova, your English coach. Let’s explore together.');return;}if(a==='transfer-audio'||a==='transfer-slow'){speak('The robot is behind the gym.',a==='transfer-slow');return;}if(a==='transfer-right'){transfer=true;notice='正确！这次地点换成了体育馆。';render();return;}if(a==='transfer-wrong'){notice='再听一次，注意 gym 和 behind。';render();return;}if(a==='listen'||a==='slow'){speak(message,a==='slow');return;}if(a==='stop'){stopSpeech();return;}if(a==='subtitle'){subtitles=!subtitles;render();return;}if(a==='phrase-help'){submit('这句话怎么说');return;}if(a==='hint'){const h=!s.started?['Where does our mission start?','Look for the festival organiser.','Go to the plaza and collect the mission.']:s.clues.length<3?['What evidence do we have so far?','A witness and the art room may help.','Ask the librarian about Pip. Check the art room note and ask about the decoration.']:!s.awake?['What does Pip look like?','Remember the blue light.','Visit the greenhouse, select the blue-light robot, and press the green button.']:!s.following?['Pip is ready to move.','How can you invite it along?','Try saying: Follow me, Pip.']:['Where did we start?','The festival needs Pip back.','Return to the plaza and hand in the mission.'];say(h[Math.min(hint++,2)],`提示 ${Math.min(hint,3)}/3 · ${goal()}。由你决定并完成操作。`);return;}if(a==='mic'){mic('coach');return;}if(a==='reset'){const d=document.createElement('dialog');d.innerHTML='<h2>重新开始冒险？</h2><p>这会清除本浏览器里的当前关卡进度。</p><div class="actions"><button class="secondary" id="cancel-reset">继续冒险</button><button class="primary" id="confirm-reset">确认重置</button></div>';document.body.append(d);d.showModal();d.querySelector('#cancel-reset').onclick=()=>d.remove();d.querySelector('#confirm-reset').onclick=()=>{cancelVoice();stopSpeech();s=initial();player={x:150,y:460};companion={x:115,y:480};destination=null;keys.clear();nearby=null;npcLine='';npcZh='';heardBy='';lastQuestion='';npcReplies={};npcResponses={};npcTopics={};listeningContext=null;discussionActive=false;discussionChecking=false;try{localStorage.removeItem('campus-position');localStorage.removeItem(KEY);}catch{}view='welcome';transfer=false;chosen=false;hint=0;guideHighlight='';coachStatus='';d.remove();notice='🔄 进度已重置，我们重新出发。';const g=guidance(s);say(g.en,g.zh);};return;}}
let voiceDisplay=null;
function voiceMessage(state){
 if(state.error)return state.error;
 return ({preparing:'正在准备麦克风和语音检测…',listening:'正在听，请开始说话',speaking:'正在听，你可以继续说',waiting:`等待你继续 · 静音 ${((2000-state.remaining)/1000).toFixed(1)} / 2 秒`,reconnecting:'正在继续识别，已保留前面的话',finalizing:'正在整理完整转写…',review:'有一部分文字尚未定稿，请确认或重说',done:'本次完整识别结果',empty:'没有识别到内容，请重说',cancelled:'已取消，本次内容没有提交'})[state.phase]||'';
}
function voiceTriggerButton(target,idleLabel){return btn(recording?'■ 说完了':'🎙 '+idleLabel,target==='story'?'story-mic':target==='coach'?'coach-talk':'npc-mic','primary'+(recording?' recording':''));}
function voicePanel(target,npcId=''){
 const d=voiceDisplay;if(!d||d.target!==target||(target==='npc'&&d.npcId!==npcId))return '';
 const live=recording&&d.phase!=='review';
 return `<section class="voice-capture" aria-label="本次语音输入"><strong data-voice-state role="status">${esc(voiceMessage(d))}</strong><p class="voice-live" data-voice-live>${esc(d.text||'识别内容会显示在这里')}</p><div class="actions">${live?btn('说完了','voice-finish','primary','data-voice-stop '+(['preparing','finalizing'].includes(d.phase)?'disabled':''))+btn('取消','voice-cancel'):''}${d.phase==='review'?btn('确认并发送','voice-confirm-text','primary'):''}${!live?btn('重新说一次','voice-retry','chip'):''}</div></section>`;
}
function updateVoiceLive(){if(!voiceDisplay)return;document.querySelectorAll('[data-voice-state]').forEach(el=>el.textContent=voiceMessage(voiceDisplay));document.querySelectorAll('[data-voice-live]').forEach(el=>el.textContent=voiceDisplay.text||'识别内容会显示在这里');document.querySelectorAll('[data-voice-stop]').forEach(el=>el.disabled=['preparing','finalizing'].includes(voiceDisplay.phase));}
function cancelVoice(renderUI=false){const turn=recording;recording=null;turn?.abort();if(turn&&voiceDisplay)voiceDisplay={...voiceDisplay,phase:'cancelled'};if(renderUI)render();}
function deliverVoice(d){
 if(d.target==='npc'){if(view==='map'&&nearest(player,s)?.id===d.npcId)npcSubmit(d.text);else{d.phase='cancelled';render();}}
 else if(d.target==='story'){if(activeStory)storyAnswer(d.text);else{d.phase='cancelled';render();}}
 else submit(d.text);
}
function mic(target='npc'){
 if(recording){if(voiceDisplay?.phase!=='preparing')recording.stop();return;}
 if(target==='story'&&!activeStory)return;
 const contact=nearest(player,s);if(target==='npc'&&s.prepared&&contact?.id==='organiser'&&!s.complete){if(interactionMode(contact,s)==='mission')action('start');else replayNpc(contact);return;}
 if(s.complete&&target==='npc'){speak(reply(nearest(player,s)||NPCS[0],s,'').en);return;}
 const R=window.SpeechRecognition||window.webkitSpeechRecognition;
 if(!R){const error='此浏览器不支持语音识别，请使用文字交流。';if(target==='coach')coachStatus=error;else micError=error;render();openTyping(target);return;}
 if(target==='npc'&&(!contact||!s.prepared))return;
 const start=()=>{
  micApproved=true;stopSpeech();destination=null;keys.clear();micError='';coachStatus='';
  voiceDisplay={target,npcId:contact?.id||'',phase:'preparing',text:'',remaining:2000};
  const turn=createVoiceTurn({Recognition:R,createVAD:createBrowserVAD,
   onUpdate:update=>{if(recording!==turn)return;voiceDisplay={...voiceDisplay,...update};updateVoiceLive();},
   onComplete:result=>{if(recording!==turn)return;recording=null;voiceDisplay={...voiceDisplay,...result,phase:!result.text?'empty':result.needsReview?'review':'done'};render();if(result.text&&!result.needsReview)deliverVoice(voiceDisplay);},
   onError:(code,text)=>{if(recording!==turn)return;recording=null;const errors={'not-allowed':'麦克风权限未开启，请允许后重试或打字。','no-speech':'没有检测到说话，请重新说一次。','vad-unavailable':'语音检测未能启动，请重试或打字，不会提前提交。','vad-stalled':'语音检测中断，本次没有提交，请重说。','not-ready':'语音还没准备好，请重新开启。','network':'浏览器语音服务连接失败，本次没有提交。','recognition-restarts':'识别服务多次中断，本次没有提交，请重试。','recognition-timeout':'识别服务启动超时，请重试或打字。'};voiceDisplay={...voiceDisplay,text,phase:'error',error:errors[code]||'语音识别中断，本次没有提交，请重新说一次或打字。'};render();}
  });
  recording=turn;render();void turn.start();
 };
 if(micApproved){start();return;}
 const d=document.createElement('dialog');d.innerHTML='<h2>开启语音交谈</h2><p>说话时持续识别，连续静音 2 秒后才回答，也可以点“说完了”。语音活动检测在本地运行；浏览器可能使用其远程语音服务。本应用不保存录音。</p><div class="actions"><button class="secondary" id="no-mic">改用文字</button><button class="primary" id="yes-mic">开启麦克风</button></div>';document.body.append(d);d.showModal();d.querySelector('#no-mic').onclick=()=>{d.remove();openTyping(target);};d.querySelector('#yes-mic').onclick=()=>{d.remove();start();};
}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.speak){speak(b.dataset.speak);return;}if(b.dataset.action)action(b.dataset.action,b.dataset.value);});document.addEventListener('submit',e=>{if(e.target.id==='npc-talk'){e.preventDefault();npcSubmit(new FormData(e.target).get('question')||'');return;}if(e.target.id==='story-talk'){e.preventDefault();storyAnswer(new FormData(e.target).get('answer')||'');return;}if(e.target.id!=='talk')return;e.preventDefault();submit(new FormData(e.target).get('utterance')||'');});render();

document.addEventListener('change',e=>{if(e.target.matches('[data-rate-choice]')){const rate=Number(e.target.value);if(!speechRates.includes(rate))return;stopSpeech();speechRate=rate;voiceTested=false;voiceStatus='语速已设为 '+speechRate.toFixed(2)+'×，下次播放生效';try{localStorage.setItem('campus-speech-rate',String(speechRate));}catch{notice='浏览器未允许保存语速，本次设置仅在当前页面有效。';}render();return;}if(e.target.id==='voice-choice'){stopSpeech();voiceTested=false;preferredVoice=e.target.value;voiceStatus='音色已更改，点击试听确认';try{localStorage.setItem('campus-voice',preferredVoice);voiceSaveError=false;}catch{voiceSaveError=true;}render();}});
window.speechSynthesis?.addEventListener('voiceschanged',()=>{const select=document.querySelector('#voice-choice');if(select)select.innerHTML=voiceOptions();updateVoiceStatus();});

document.addEventListener('click',e=>{const world=e.target.closest('#world');if(!world||view!=='map')return;const npc=e.target.closest('[data-npc]');if(npc){const id=npc.dataset.npc;if(id==='pip'&&s.discovered&&!s.complete){winPip();return;}if(s.prepared&&nearest(player,s)?.id===id){destination=null;keys.clear();const n=nearest(player,s);if(npcAudio(n)){if(recording){cancelVoice();}replayNpc(n);}else mic('npc');}else if(!recording){targetNpc(id);}return;}if(recording)return;const rect=world.getBoundingClientRect();destination=bound({x:(e.clientX-rect.left)/rect.width*1000,y:(e.clientY-rect.top)/rect.height*600});world.focus({preventScroll:true});});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const d=document.querySelector('dialog[open]');if(d)d.close();else document.querySelectorAll('.transcript[open],.typing-fallback[open]').forEach(el=>el.open=false);return;}if(view!=='map'||document.querySelector('dialog')||e.target.closest('input,textarea,select,[contenteditable=true]'))return;const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright','w','a','s','d'].includes(k)){if(recording)return;e.preventDefault();if(!e.repeat){const d={arrowup:[0,-8],w:[0,-8],arrowdown:[0,8],s:[0,8],arrowleft:[-8,0],a:[-8,0],arrowright:[8,0],d:[8,0]}[k];player=bound({x:player.x+d[0],y:player.y+d[1]});destination=null;}keys.add(k);}if(k==='e'&&!e.repeat&&s.prepared){const n=nearest(player,s);if(n?.id==='pip'&&s.discovered&&!s.complete){e.preventDefault();winPip();}else if(n){e.preventDefault();mic('npc');}}if(k==='r'&&!e.repeat){e.preventDefault();if(lastSpoken)speak(lastSpoken);}});
document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();destination=null;});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();destination=null;if(recording)cancelVoice(true);}});requestAnimationFrame(frame);

document.addEventListener('focusin',e=>{if(e.target.closest('input,textarea,select')){keys.clear();destination=null;}});
